add_action( 'woocommerce_register_form_start', 'perfectpixel_registration_name_fields' );
add_filter( 'woocommerce_registration_errors', 'perfectpixel_registration_name_validate', 10, 3 );
add_action( 'woocommerce_created_customer', 'perfectpixel_registration_name_save' );

function perfectpixel_registration_name_fields() {
	foreach ( array( 'billing_first_name' => __( 'First name', 'woocommerce' ), 'billing_last_name' => __( 'Last name', 'woocommerce' ) ) as $key => $label ) {
		$value = isset( $_POST[ $key ] ) ? sanitize_text_field( wp_unslash( $_POST[ $key ] ) ) : '';
		printf(
			'<p class="form-row form-row-%1$s"><label for="reg_%2$s">%3$s <span class="required">*</span></label><input type="text" class="input-text" name="%2$s" id="reg_%2$s" value="%4$s" autocomplete="%5$s" required></p>',
			'billing_first_name' === $key ? 'first' : 'last',
			esc_attr( $key ),
			esc_html( $label ),
			esc_attr( $value ),
			'billing_first_name' === $key ? 'given-name' : 'family-name'
		);
	}
	echo '<div class="clear"></div>';
}

function perfectpixel_registration_name_validate( $errors, $username, $email ) {
	if ( is_checkout() ) {
		return $errors; // The checkout has its own name fields.
	}
	if ( empty( $_POST['billing_first_name'] ) ) {
		$errors->add( 'billing_first_name_error', '{{reg_first_name_error}}' );
	}
	if ( empty( $_POST['billing_last_name'] ) ) {
		$errors->add( 'billing_last_name_error', '{{reg_last_name_error}}' );
	}
	return $errors;
}

function perfectpixel_registration_name_save( $customer_id ) {
	foreach ( array( 'first_name', 'last_name' ) as $field ) {
		if ( ! empty( $_POST[ 'billing_' . $field ] ) ) {
			$value = sanitize_text_field( wp_unslash( $_POST[ 'billing_' . $field ] ) );
			update_user_meta( $customer_id, $field, $value );
			update_user_meta( $customer_id, 'billing_' . $field, $value );
		}
	}
}
